import { getDomain } from '@helpers/domain.helper';
import { round } from '@helpers/mathHelper';

import { IHikingGpx, IHikingGpxPoint } from '../../Hiking/@types/hiking.types';
import { IWorkoutFull } from '../../Workouts/@types/workouts.types';

const schemaLocations = [
  'http://www.topografix.com/GPX/1/1',
  'http://www.topografix.com/GPX/1/1/gpx.xsd',
];
export interface IGetGPXStringTracks {
  name?: string;
  description?: string;
  coordinates: Array<[number, number] | [number, number, number]>;
}

export interface IGetGPXStringPoints {
  name: string;
  description?: string;
  coordinate: [number, number] | [number, number, number];
}

export interface IGetGPXStringOptions {
  name?: string;
  description?: string;
  author?: string;
  date?: Date;
  asRoute?: boolean;
}

export const getGPXStringByCoordinates = (
  tracks?: IGetGPXStringTracks[],
  points?: IGetGPXStringPoints[],
  options?: IGetGPXStringOptions,
) => {
  return `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
  <gpx
      xmlns="http://www.topografix.com/GPX/1/1"
      xmlns:gpxtpx="http://www.garmin.com/xmlschemas/TrackPointExtension/v1"
      xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
      creator="${getDomain()}"
      version="1.1"
      xsi:schemaLocation="${schemaLocations.join(' ')}"
  >
      <metadata>
          ${options?.name ? `<name>${options.name}</name>` : ''}
          ${options?.description ? `<desc>${options.description}</desc>` : ''}
          ${options?.author ? `<author><name>${options.author}</name></author>` : ''}
          <time>${new Date(options?.date ?? new Date()).toISOString()}</time>
      </metadata>
      ${points
        ?.map((point) => {
          return `<wpt lat="${point.coordinate[0]}" lon="${point.coordinate[1]}">
          ${point.coordinate[2] ? `<ele>${point.coordinate[2]}</ele>` : ''}
          ${point.name ? `<name>${point.name}</name>` : ''}
          ${point?.description ? `<desc>${point.description}</desc>` : ''}
        </wpt>`;
        })
        ?.join('')}
      ${
        !options?.asRoute
          ? tracks
              ?.map((track) => {
                return `<trk>
          ${track?.name ? `<name>${track.name}</name>` : ''}
          ${track?.description ? `<desc>${track.description}</desc>` : ''}
          <trkseg>
            ${track.coordinates
              .map((point) => {
                return `<trkpt lat="${point[0]}" lon="${point[1]}">
              ${point[2] ? `<ele>${point[2]}</ele>` : ''}
              <time>${new Date().toISOString()}</time>
            </trkpt>`;
              })
              ?.join('')}
          </trkseg>
      </trk>`;
              })
              ?.join('')
          : ''
      }
      ${
        options?.asRoute
          ? tracks
              ?.map((track) => {
                return `<rte>
          ${track?.name ? `<name>${track.name}</name>` : ''}
          ${track?.description ? `<desc>${track.description}</desc>` : ''}

          ${track.coordinates
            .map((point) => {
              return `<rtept lat="${point[0]}" lon="${point[1]}">
            ${point[2] ? `<ele>${point[2]}</ele>` : ''}
          </rtept>`;
            })
            ?.join('')}
      </rte>`;
              })
              ?.join('')
          : ''
      }
    </gpx>
      `
    .replaceAll(/[\r\n]/g, '')
    .replaceAll(/>\s+</g, '><')
    .replaceAll(/\s+/g, ' ');
};

export const downloadStringAsGpx = (gpxString: string, name = 'track') => {
  const a = document.createElement('a');
  a.download = `${name}.gpx`;
  const bb = new Blob([gpxString], { type: 'application/gpx+xml' });
  a.href = window.URL.createObjectURL(bb);
  a.click();
  window.URL.revokeObjectURL(a.href);
  a.remove();
};

export const downloadGpx = (
  tracks?: IGetGPXStringTracks[],
  points?: IGetGPXStringPoints[],
  options?: IGetGPXStringOptions,
) => {
  const gpxString = getGPXStringByCoordinates(tracks, points, options);

  downloadStringAsGpx(gpxString, options?.name);
};

interface IGetGPXFromHikingGpxOptions {
  name?: string;
  description?: string;
  author?: string;
  creator?: string;
  dateStart?: Date;
}

const defaultProps: IGetGPXFromHikingGpxOptions = {
  name: 'Трек',
  description: '',
  author: 'Походник',
  creator: getDomain(),
  dateStart: new Date(),
};

export const getGPXStringFromHikingGpx = (
  hikingGpx: IHikingGpx,
  props: IGetGPXFromHikingGpxOptions = defaultProps,
) => {
  return `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
    <gpx
        xmlns="http://www.topografix.com/GPX/1/1"
        xmlns:gpxtpx="http://www.garmin.com/xmlschemas/TrackPointExtension/v1"
        xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
        creator="${props.creator}"
        version="1.1"
        xsi:schemaLocation="${schemaLocations
          .concat([
            'http://www.garmin.com/xmlschemas/TrackPointExtension/v1',
            'http://www.garmin.com/xmlschemas/TrackPointExtensionv1.xsd',
          ])
          .join(' ')}"
    >
        <metadata>
            <name>${props.name}</name>
            <desc>${props.description}</desc>
                <author>
                    <name>${props.author}</name>
                </author>
        </metadata>
        <trk>
            <name>${props.name}</name>
            <trkseg>
            ${hikingGpx.track.map(({ date, point: [lat, lon, alt], hr, temp }) => {
              return `<trkpt lat="${lat}" lon="${lon}">
                <time>${date.toISOString()}</time>
                ${alt ? `<ele>${alt}</ele>` : ''}
                ${
                  hr !== null || temp !== null
                    ? `
                <extensions>
                  <gpxtpx:TrackPointExtension>
                    ${alt !== null ? `<gpxtpx:hr>${hr}</gpxtpx:hr>` : ''}
                    ${temp !== null ? `<gpxtpx:atemp>${temp}</gpxtpx:atemp>` : ''}
                  </gpxtpx:TrackPointExtension>
                </extensions>
                `
                    : ''
                }
              </trkpt>
              </trkseg>
            </trk>
          </gpx>`.replaceAll(/>\s+</g, '><');
            })}
        `;
};

export const downloadGpxFromHikingGpx = (data: IHikingGpx, props: IGetGPXFromHikingGpxOptions) => {
  const str = getGPXStringFromHikingGpx(data, props);
  downloadStringAsGpx(str, props.name);
};

export const getGPXStringFromWorkout = (
  workout: IWorkoutFull,
  props: IGetGPXFromHikingGpxOptions = defaultProps,
) => {
  const mapPoints = (track: IHikingGpxPoint[]): string => {
    const points: string[] = [];

    track.forEach(({ date, point: [lat, lon, alt], hr, temp }) => {
      const innerTrkptContents: string[] = [];

      if (date) innerTrkptContents.push(`<time>${date.toISOString()}</time>`);
      if (alt) innerTrkptContents.push(`<ele>${round(alt, 2)}</ele>`);

      if (hr !== null || temp !== null) {
        const extArr: string[] = [];
        alt !== null && extArr.push(`<gpxtpx:hr>${hr}</gpxtpx:hr>`);
        temp !== null && extArr.push(`<gpxtpx:atemp>${temp}</gpxtpx:atemp>`);
        extArr.length > 0 &&
          innerTrkptContents.push(`<extensions>
      <gpxtpx:TrackPointExtension>
        ${extArr.join('\n')}
      </gpxtpx:TrackPointExtension>
    </extensions>`);
      }

      points.push(`<trkpt lat="${lat}" lon="${lon}">
      ${innerTrkptContents.length > 0 ? innerTrkptContents.join('\n') : ''}
    </trkpt>`);
    });

    return points.join('\n');
  };

  return `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
  <gpx
      xmlns="http://www.topografix.com/GPX/1/1"
      xmlns:gpxtpx="http://www.garmin.com/xmlschemas/TrackPointExtension/v1"
      xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
      creator="${props.creator ?? 'pohodnik_workout_exporter'}"
      version="1.1"
      xsi:schemaLocation="${schemaLocations
        .concat([
          'http://www.garmin.com/xmlschemas/TrackPointExtension/v1',
          'http://www.garmin.com/xmlschemas/TrackPointExtensionv1.xsd',
        ])
        .join(' ')}"
  >
      <metadata>
        <name>${workout.name || props.name}</name>
        ${workout.description || props.description ? `<desc>${workout.description || props.description}</desc>` : ''}
        <author>
          <name>${workout.user.name || props.author}</name>
          <link href="https://${getDomain()}/user/${workout.user.id}">
            <text>Страница походника</text>
          </link>
        </author>
      </metadata>
      <trk>
        <name>${workout.name || props.name}</name>
        <trkseg>
          ${mapPoints(workout.track)}
            </trkseg>
          </trk>
        </gpx>`.replaceAll(/>\s+</g, '><');
};

export const downloadGpxFromWorkout = (
  workout: IWorkoutFull,
  props: IGetGPXFromHikingGpxOptions,
) => {
  const str = getGPXStringFromWorkout(workout, props);
  downloadStringAsGpx(str, props.name);
};
